function uploadS3(S3DataStr) {
    const url = '/dev/upload/'
    return new Promise((resolve,reject)=>{
		CIQ.axios.post(url,S3DataStr,{withCredentials: true})
		.then(res=>{
			resolve(res)
		}).catch(err=>{
			reject(err)
		})
	})
}

